using System.Text.Json;
namespace Reforged.Server;
public sealed record RuntimePlayerTransactionSmokeReport(bool Passed,IReadOnlyList<string> Checks,IReadOnlyList<string> Failures){public string ToJson()=>JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true});public static RuntimePlayerTransactionSmokeReport Run(){var c=new List<string>();var f=new List<string>();void Check(bool x,string n){c.Add(n);if(!x)f.Add(n);}var s=new RuntimePlayerTransactionService(new(8,TimeSpan.FromMinutes(2),false,false,false));var now=DateTimeOffset.Parse("2026-01-01T00:00:00Z");var o=s.Offer("tx1","alice","bob",new[]{new RuntimeTransferLine(RuntimePlayerTransferKind.Item,"sword",1)},new[]{new RuntimeTransferLine(RuntimePlayerTransferKind.Currency,"gold",25)},now);Check(o.Accepted,"offer");var a=s.Accept("tx1","bob",now.AddSeconds(5));Check(a.Accepted&&a.OwnerRequests.Count==2,"accept-owner-routing");Check(!s.Commit("tx1",1).Accepted,"revision-conflict");Check(s.Commit("tx1",a.Revision).Accepted,"commit");Check(!s.Offer("tx2","alice","bob",new[]{new RuntimeTransferLine(RuntimePlayerTransferKind.Item,"quest",1,true)},Array.Empty<RuntimeTransferLine>(),now).Accepted,"quest-item-restriction");var o2=s.Offer("tx3","alice","bob",new[]{new RuntimeTransferLine(RuntimePlayerTransferKind.Currency,"gold",1)},Array.Empty<RuntimeTransferLine>(),now);Check(o2.Accepted&&s.Disconnect("tx3","alice").Accepted,"disconnect-cancel");Check(s.ValidateState().Count==0,"state-invariants");return new(f.Count==0,c,f);}}
